package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
)

// JSONTheme represents a theme loaded from JSON configuration.
// It implements the fyne.Theme interface.
//
// Since: 2.5
type JSONTheme struct {
	colors map[fyne.ThemeColorName]map[fyne.ThemeVariant]color.Color
	sizes  map[fyne.ThemeSizeName]float32
	fonts  map[string]fyne.Resource
}

type jsonThemeData struct {
	Colors map[string]map[string]string `json:"colors"`
	Sizes  map[string]float32           `json:"sizes"`
}

// FromJSON parses a JSON theme configuration and returns a Theme.
// The JSON format supports color definitions with hex strings (#RGB, #RGBA, #RRGGBB, #RRGGBBAA)
// and size definitions as float values.
//
// Example JSON:
//   {
//     "colors": {
//       "background": {"dark": "#303030", "light": "#ffffff"},
//       "foreground": {"dark": "#fff", "light": "#212121"}
//     },
//     "sizes": {
//       "text": 14,
//       "padding": 4
//     }
//   }
//
// Since: 2.5
func FromJSON(data []byte) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(string(data)))
}

// FromJSONReader parses a JSON theme configuration from an io.Reader and returns a Theme.
// See FromJSON for the JSON format specification.
//
// Since: 2.5
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var data jsonThemeData
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&data); err != nil {
		return nil, fmt.Errorf("failed to parse JSON theme: %w", err)
	}

	theme := &JSONTheme{
		colors: make(map[fyne.ThemeColorName]map[fyne.ThemeVariant]color.Color),
		sizes:  make(map[fyne.ThemeSizeName]float32),
		fonts:  make(map[string]fyne.Resource),
	}

	// Parse colors
	for colorName, variants := range data.Colors {
		colorMap := make(map[fyne.ThemeVariant]color.Color)
		for variantName, hexColor := range variants {
			col, err := parseHexColor(hexColor)
			if err != nil {
				return nil, fmt.Errorf("invalid color %s.%s: %w", colorName, variantName, err)
			}

			var variant fyne.ThemeVariant
			switch variantName {
			case "dark":
				variant = VariantDark
			case "light":
				variant = VariantLight
			default:
				return nil, fmt.Errorf("unknown variant: %s", variantName)
			}

			colorMap[variant] = col
		}
		theme.colors[fyne.ThemeColorName(colorName)] = colorMap
	}

	// Parse sizes
	for sizeName, size := range data.Sizes {
		theme.sizes[fyne.ThemeSizeName(sizeName)] = size
	}

	return theme, nil
}

// parseHexColor parses hex color strings in formats: #RGB, #RGBA, #RRGGBB, #RRGGBBAA
func parseHexColor(s string) (color.Color, error) {
	s = strings.TrimPrefix(s, "#")

	var r, g, b, a uint8 = 0, 0, 0, 255

	switch len(s) {
	case 3: // #RGB
		rv, _ := strconv.ParseUint(s[0:1], 16, 8)
		gv, _ := strconv.ParseUint(s[1:2], 16, 8)
		bv, _ := strconv.ParseUint(s[2:3], 16, 8)
		r, g, b = uint8(rv*17), uint8(gv*17), uint8(bv*17)
	case 4: // #RGBA
		rv, _ := strconv.ParseUint(s[0:1], 16, 8)
		gv, _ := strconv.ParseUint(s[1:2], 16, 8)
		bv, _ := strconv.ParseUint(s[2:3], 16, 8)
		av, _ := strconv.ParseUint(s[3:4], 16, 8)
		r, g, b, a = uint8(rv*17), uint8(gv*17), uint8(bv*17), uint8(av*17)
	case 6: // #RRGGBB
		rv, _ := strconv.ParseUint(s[0:2], 16, 8)
		gv, _ := strconv.ParseUint(s[2:4], 16, 8)
		bv, _ := strconv.ParseUint(s[4:6], 16, 8)
		r, g, b = uint8(rv), uint8(gv), uint8(bv)
	case 8: // #RRGGBBAA
		rv, _ := strconv.ParseUint(s[0:2], 16, 8)
		gv, _ := strconv.ParseUint(s[2:4], 16, 8)
		bv, _ := strconv.ParseUint(s[4:6], 16, 8)
		av, _ := strconv.ParseUint(s[6:8], 16, 8)
		r, g, b, a = uint8(rv), uint8(gv), uint8(bv), uint8(av)
	default:
		return nil, fmt.Errorf("invalid hex color format: %s", s)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// Color returns the themed color for the specified color name and variant.
func (t *JSONTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	if variants, ok := t.colors[name]; ok {
		if col, ok := variants[variant]; ok {
			return col
		}
	}
	// Fallback to default theme
	return DefaultTheme().Color(name, variant)
}

// Font returns the themed font resource for the specified text style.
func (t *JSONTheme) Font(style fyne.TextStyle) fyne.Resource {
	// Fallback to default theme fonts
	return DefaultTheme().Font(style)
}

// Icon returns the themed icon resource for the specified icon name.
func (t *JSONTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	// Fallback to default theme icons
	return DefaultTheme().Icon(name)
}

// Size returns the themed size for the specified size name.
func (t *JSONTheme) Size(name fyne.ThemeSizeName) float32 {
	if size, ok := t.sizes[name]; ok {
		return size
	}
	// Fallback to default theme
	return DefaultTheme().Size(name)
}

