package binding

import (
	"fmt"
	"sync"
)

// sprintfBinding is a String binding that formats values from multiple source bindings
type sprintfBinding struct {
	base
	format  string
	sources []DataItem
	lock    sync.RWMutex
}

// NewSprintf creates a new String binding that formats its content using fmt.Sprintf with the
// given format string and source bindings. The binding listens to all sources and updates
// automatically when any source changes.
//
// Example:
//   name := binding.NewString()
//   age := binding.NewInt()
//   formatted := binding.NewSprintf("Name: %s, Age: %d", name, age)
//
// Since: 2.5
func NewSprintf(format string, sources ...DataItem) String {
	b := &sprintfBinding{
		format:  format,
		sources: sources,
	}

	// Listen to all source bindings
	for _, src := range sources {
		src.AddListener(NewDataListener(func() {
			b.trigger()
		}))
	}

	return b
}

// Get returns the formatted string value
func (b *sprintfBinding) Get() (string, error) {
	b.lock.RLock()
	defer b.lock.RUnlock()

	values := make([]interface{}, len(b.sources))
	for i, src := range b.sources {
		if strSrc, ok := src.(String); ok {
			val, err := strSrc.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		} else if intSrc, ok := src.(Int); ok {
			val, err := intSrc.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		} else if floatSrc, ok := src.(Float); ok {
			val, err := floatSrc.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		} else if boolSrc, ok := src.(Bool); ok {
			val, err := boolSrc.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		} else if untypedSrc, ok := src.(Untyped); ok {
			val, err := untypedSrc.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		} else {
			values[i] = src
		}
	}

	return fmt.Sprintf(b.format, values...), nil
}

// Set is not supported for sprintf bindings as they are read-only
func (b *sprintfBinding) Set(string) error {
	return fmt.Errorf("cannot set value on a sprintf binding")
}

// StringToStringWithFormat creates a new String binding that converts the value from a source
// String binding using fmt.Sprintf with the given format string.
//
// Example:
//   username := binding.NewString()
//   greeting := binding.StringToStringWithFormat(username, "Hello, %s!")
//
// Since: 2.5
func StringToStringWithFormat(source String, format string) String {
	return NewSprintf(format, source)
}

