package validation

import (
	"fyne.io/fyne/v2"
)

// NewAllStrings creates a validator that chains multiple StringValidators together.
// The returned validator will run all the provided validators in sequence against the input string.
// It returns the first error encountered, or nil if all validators pass.
//
// This is useful for combining multiple validation rules, such as checking both format and content.
//
// Since: 2.5
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(text string) error {
		for _, validator := range validators {
			if validator == nil {
				continue
			}
			if err := validator(text); err != nil {
				return err
			}
		}
		return nil
	}
}

